async function waitForTeamIcon(maxRetries = 5, delayMs = 500) {
    for (let i = 0; i < maxRetries; i++) {
        const iconUrl = h();
        if (iconUrl) return iconUrl;
        await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    return null;
}

// In init function:
